with enriched as (select *, last_value(level) ignore nulls over (order by salary, id rows between unbounded preceding and current row) as last_known_level, min(salary) over (partition by year(hire_date), manager_id) as hire_date_year_min_salary, max(salary) over w_ordered as hire_date_month_max_salary, ntile(4) over w_part as salary_bucket, first_value(job_title, true) over (partition by level order by salary, id rows between unbounded preceding and current row) as first_known_job_title from employees where dept_id = 18 window w_ordered as (partition by month(hire_date), level), w_part as (partition by level order by salary, id)) select id, email, job_title, hire_date, hire_date_month_max_salary, first_known_job_title from enriched;
